namespace Bingo.Domain.Boards;

public sealed class BoardRequirementDropSnapshot { private BoardRequirementDropSnapshot() { } public BoardRequirementDropSnapshot(Guid id, Guid requirementId, Guid sourceDropId, string boss, string item, string displayRate, decimal? probability, int? maximum, decimal? ehb) { Id = id; RequirementId = requirementId; SourceDropId = sourceDropId; BossName = boss; ItemName = item; DisplayRate = displayRate; NumericProbability = probability; MaximumContribution = maximum; EhbPerContribution = ehb; } public Guid Id { get; private set; } public Guid RequirementId { get; private set; } public Guid SourceDropId { get; private set; } public string BossName { get; private set; } = string.Empty; public string ItemName { get; private set; } = string.Empty; public string DisplayRate { get; private set; } = string.Empty; public decimal? NumericProbability { get; private set; } public int? MaximumContribution { get; private set; } public decimal? EhbPerContribution { get; private set; } }
